from django.utils import timezone

from app.customers.models import Customer

RETENTION_DAYS = 730
ANONYMISE_FIELDS = ('email', 'phone', 'address', 'rut')


class RetentionGuardMixin:
    retention_days = RETENTION_DAYS

    def eligible_for_erasure(self, customer: Customer) -> bool:
        age = timezone.now() - customer.created_at
        return age >= timedelta(days=self.retention_days)

    def anonymise(self, customer: Customer) -> None:
        updates = {field: None for field in ANONYMISE_FIELDS}
        Customer.objects.filter(pk=customer.pk).update(**updates, anonymised_at=timezone.now())


class CustomerErasureService(RetentionGuardMixin):
    def run(self, customer: Customer) -> str:
        if not self.eligible_for_erasure(customer):
            return 'retained'
        self.anonymise(customer)
        return 'anonymised'

from collections.abc import Iterator
from datetime import timedelta

from django.utils import timezone

from app.customers.models import Customer

RETENTION_DAYS = 730
ANONYMISE_FIELDS = ('email', 'phone', 'address')


def _expired_customers() -> Iterator[Customer]:
    cutoff = timezone.now() - timedelta(days=RETENTION_DAYS)
    for customer in Customer.objects.filter(created_at__lt=cutoff).iterator():
        yield customer


def anonymise_expired() -> Iterator[str]:
    yield 'customer_id,result\n'
    for customer in _expired_customers():
        updates = {field: None for field in ANONYMISE_FIELDS}
        Customer.objects.filter(pk=customer.pk).update(**updates)
        yield f'{customer.id},anonymised\n'

