from app.billing.models import Order

RETENTION_DAYS = 2190
HIDDEN_FIELDS = ('internal_notes', 'tax_snapshot', 'customer_email')


class BillingRetentionMixin:
    retention_days = RETENTION_DAYS
    hidden_fields = HIDDEN_FIELDS

    def cutoff(self):
        return timezone.now() - timedelta(days=self.retention_days)

    def export_row(self, order: Order) -> dict:
        return order.model_dump(exclude=self.hidden_fields)


class OrderPurgeService(BillingRetentionMixin):
    def purgeable(self):
        return Order.objects.filter(created_at__lt=self.cutoff(), status='void')

    def run(self) -> int:
        queryset = self.purgeable()
        rows = [self.export_row(order) for order in queryset]
        queryset.delete()
        return len(rows)

