from app.integrations.models import ApiCredential

MASK_VISIBLE_CHARS = 4


def _mask(key: str) -> str:
    if len(key) <= MASK_VISIBLE_CHARS:
        return '*' * len(key)
    return '*' * (len(key) - MASK_VISIBLE_CHARS) + key[-MASK_VISIBLE_CHARS:]


def integration_settings(request, credential_id):
    credential = ApiCredential.objects.get(pk=credential_id)
    context = {
        'provider': credential.provider,
        'api_key_masked': _mask(credential.api_key),
        'api_key_configured': bool(credential.api_key),
        'created_at': credential.created_at,
    }
    return render(request, 'integrations/settings.html', context)

